## Visual test: displays grids generated by `makeGrid` (uv grid quads) and by the
## alternative `makeTriangulatedGrid` (delaunay triangles) on a Plane3 surface.
##
## The grid is computed from two closed 2D contours forming an outer boundary and a circular hole in the middle.
##
## [←/→] — switch surface, [Space] — switch grid algorithm.

import std/[math, sequtils]
import pkg/[chroma, siwin]
import rice
import sigeo/[core, curves2d, surfaces]
import ./drawutils

const
  outerRadius = 400
  holeRadius = 100
  resolution = 32

let gridW = (outerRadius * 2 + 2).float
let gridH = gridW
let margin = 30.0

let winW = int32(margin * 2 + gridW)
let winH = int32(margin * 2 + gridH)


let app = newVisualTest(
  title = "sigeo v_grids - [←/→] surface, [Space] grid algorithm (quads / delaunay triangles)",
  size = ivec2(winW, winH),
  contentCenter = vec2(0, 0),
)


proc drawDots(ctx: DrawContext, pts: seq[Vec3], thickness: float = 1) =
  let cameraDir = normalize(ctx.viewportMatrix.inverse * vec3(0, 0, -1))
  for pt in pts:
    ctx.fillCircle(
      color = color(1, 1, 1),
      center = pt,
      radius = holeRadius / resolution / 1000 / app.camera.zoom * thickness,
      normal = cameraDir,
    )

proc drawWireframe(ctx: DrawContext, grid: Grid3, thickness: float = 1) =
  let cameraDir = normalize(ctx.viewportMatrix.inverse * vec3(0, 0, -1))
  let step =
    case grid.kind
    of Quads: 4
    of Triangles, TriangleStrip, TriangleFan: 3
  let n = (if grid.kind == Quads: 4 else: 3)
  for i in countup(0, grid.indices.high, step):
    for j in 0..<n:
      ctx.fillCapsule(
        color = color(0.75, 0.75, 0.75),
        radius = holeRadius / resolution / 1000 / app.camera.zoom / 3 * thickness,
        a = grid.points[grid.indices[i + j]].V3.vec3,
        b = grid.points[grid.indices[i + ((j + 1) mod n)]].V3.vec3,
        normal = cameraDir,
      )


let outerArc = circleArc(p2(0, 0), outerRadius)
let innerArc = circleArc(p2(outerRadius * 0.35, outerRadius * 0.35), holeRadius)

var grid: Grid3
var mesh: Mesh

var selectedSurface = 0
var useTriangulation = false

proc setSurface(surf: Surface3) =
  grid =
    if useTriangulation: surf.triangulate(@[contour(outerArc), contour(innerArc)], resolution)
    else: surf.makeGrid([Curve2 outerArc, innerArc], resolution)
  mesh = grid.toGpu

proc selectSurcace(i: int) =
  case i
  of 0: setSurface Plane3(axisX: v3(1, 0, 0), axisY: v3(0, 1, 0), axisZ: v3(0, 0, 1))
  of 1: setSurface CylinderSurface3(axisX: v3(1, 0, 0), axisY: v3(0, 0, -1), axisZ: v3(0, 1, 0), radius: 300)
  of 2: setSurface SphereSurface3(axisX: v3(1, 0, 0), axisY: v3(0, 0, -1), axisZ: v3(0, 1, 0), radius: 300)
  of 3: setSurface ThorusSurface3(axisX: v3(1, 0, 0), axisY: v3(0, 0, -1), axisZ: v3(0, 1, 0), innerRadius: 130, outerRadius: 500)
  else: discard

selectSurcace selectedSurface


app.onAutoRun proc(ctx: DrawContext) =
  ## automatically check all surfaces with both algorithms
  for algorithm in 0..<2:
    let algorithmName = if algorithm == 0: "quads" else: "delaunay"
    app.saveScreenshot "surface0_" & algorithmName
    for i in 1..<4:
      app.keyTap Key.right
      app.saveScreenshot "surface" & $i & "_" & algorithmName
    app.keyTap Key.space
    app.keyTap Key.right


app.onKey proc(e: KeyEvent) =
  if e.pressed:
    const total = 4

    case e.key
    of Key.left:
      dec selectedSurface
      if selectedSurface < 0: selectedSurface = total-1
      selectSurcace selectedSurface
      redraw e.window

    of Key.right:
      inc selectedSurface
      if selectedSurface >= total: selectedSurface = 0
      selectSurcace selectedSurface
      redraw e.window

    of Key.space:
      useTriangulation = not useTriangulation
      selectSurcace selectedSurface
      redraw e.window

    else: discard


app.run proc(ctx: DrawContext) =
  ctx.set(blendRgbx)
  ctx.fill3dMeshShadedByNormalsSingleSide(mesh, color(1.0, 0.55, 0.25) * 0.75, color(1.0, 0.55, 0.25) * 0.5)
  ctx.drawWireframe(grid)
  ctx.drawDots(grid.points.mapIt(it.V3.vec3))
